    /// closes the story.
    fn enter_row(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        if let Some((name, at)) = self.mode_menu.clone() {
            self.set_mode(&name, SendMode::ALL[at], cx);
            return;
