/// While a card is dragged near an edge of what `handle` scrolls, along
/// `axis`, scrolls it a step toward that edge; whether it scrolled.
fn drag_scroll(handle: &ScrollHandle, event: &DragMoveEvent<StoryDrag>, axis: Axis) -> bool {
    let (bounds, at) = (event.bounds, event.event.position);
    if !bounds.contains(&at) {
        return false;
    }
    let (at, start, end) = match axis {
        Axis::Vertical => (at.y, bounds.top(), bounds.bottom()),
        Axis::Horizontal => (at.x, bounds.left(), bounds.right()),
    };
    let step = if at < start + DRAG_EDGE {
        DRAG_STEP
    } else if at > end - DRAG_EDGE {
        -DRAG_STEP
    } else {
        return false;
    };
    let offset = handle.offset();
    let max = handle.max_offset().along(axis);
    let next = (offset.along(axis) + step).min(px(0.)).max(-max);
    if next == offset.along(axis) {
        return false;
    }
    handle.set_offset(offset.apply_along(axis, |_| next));
    true
}

