/// A section's column: its heading, and its cards, each with what is
/// open beneath it.
fn render_section(
    &mut self,
    section: Section,
    window: &mut Window,
    cx: &mut Context<Self>,
) -> AnyElement {
    let theme = cx.theme().clone();
    let muted = theme.muted_foreground;
    let heading = self.render_heading(section, cx);
    let mut cards: Vec<AnyElement> = Vec::new();
    // While the plan is read: skeleton cards, never an empty column.
    if !self.loaded {
        if section == Section::Next
            && let Some(why) = self.load_error.clone()
        {
            cards.push(
                gpui_kit::TestSupportExt::test_support(
                    h_flex()
                        .id("planning-load-error")
                        .gap_2()
                        .items_center()
                        .child(div().flex_1().text_sm().text_color(theme.danger).child(why))
                        .child(
                            Button::new("planning-load-retry")
                                .ghost()
                                .xsmall()
                                .label("Try again")
                                .tooltip("Read the plan again")
                                .on_click(cx.listener(|this, _, _, cx| this.read_again(cx))),
                        ),
                )
                .into_any_element(),
            );
        } else {
            cards.push(
                gpui_kit::TestSupportExt::test_support(
                    v_flex()
                        .id(SharedString::from(format!(
                            "planning-loading-{}",
                            section.key()
                        )))
                        .gap(CARD_GAP)
                        .child(skeleton_card(cx))
                        .child(skeleton_card(cx)),
                )
                .into_any_element(),
            );
        }
        return self.render_column(section.key(), heading, cards, cx);
    }
    let about = self.panel_about();
    let panel_wanted = self.drafting.is_some() || !self.proposals.is_empty();
    if section == Section::Backlog && panel_wanted && about.is_none() {
        // Proposals kept from before come back in their panel.
        if self.drafting.is_none() {
            self.open_draft_panel(None, false, window, cx);
        }
        cards.push(self.render_draft_panel(window, cx));
    }
    let gap = self.gap.get();
    let count = self.sections[section_ix(section)].len();
    let takes_drops = matches!(section, Section::Backlog | Section::Next);
    if count == 0 {
        let empty = div().id(SharedString::from(format!(
            "planning-empty-{}",
            section.key()
        )));
        // An empty column that takes drops takes them at its top.
        let empty = if takes_drops {
            self.drop_zone(section, 0, empty, cx)
        } else {
            empty
        };
        // Lets UI tests find the empty state; inert in normal builds.
        cards.push(
            gpui_kit::TestSupportExt::test_support(
                empty.child(empty_line(section.empty(), muted)),
            )
            .into_any_element(),
        );
    }
    for ix in 0..count {
        let name = self.sections[section_ix(section)][ix].name.clone();
        let open = self.open.as_ref().is_some_and(|open| open.name == name);
        cards.push(self.render_row(section, ix, open, gap, window, cx));
        if open {
            let steps = self.story(&name).map_or(0, |story| story.steps().len());
            for at in 0..steps {
                self.step_focus(&name, at, cx);
            }
            let cited = self.story(&name).map_or(0, |story| story.spec.len());
            for at in 0..cited {
                self.row_focus(&format!("cite:{name}:{at}"), cx);
            }
            cards.push(self.render_open(&name, window, cx));
            if let Some(findings) = self.render_findings(Some(&name), window, cx) {
                cards.push(div().pl(px(12.)).child(findings).into_any_element());
            }
        }
        if panel_wanted && about.as_deref() == Some(name.as_str()) {
            if self.drafting.is_none() {
                self.open_draft_panel(Some(name.clone()), false, window, cx);
            }
            cards.push(self.render_draft_panel(window, cx));
        }
    }
    if section == Section::Next {
        let new_story = self
            .drop_zone(
                section,
                count,
                h_flex()
                    .id(SharedString::from(format!(
                        "planning-new-story-{}",
                        section.key()
                    )))
                    .h(px(28.))
                    .px_3()
                    .gap_2()
                    .items_center()
                    .rounded(theme.radius)
                    .cursor_pointer()
                    .text_sm()
                    .text_color(muted)
                    .aria_label("New story")
                    .tooltip(move |window, cx| {
                        gpui_kit::component::tooltip::Tooltip::new(format!(
                            "Add a story here ({MOD}N)"
                        ))
                        .build(window, cx)
                    })
                    .hover(|row| row.bg(theme.list_hover)),
                cx,
            )
            .on_click(cx.listener(move |this, _, window, cx| this.new_story(window, cx)))
            .child(Icon::new(IconName::Plus).xsmall())
            .child("New story");
        cards.push(gpui_kit::TestSupportExt::test_support(new_story).into_any_element());
    }
    self.render_column(section.key(), heading, cards, cx)
}

/// `element` as somewhere a dragged story can be dropped, at place `at`
/// of `section`.
fn drop_zone(
    &self,
    section: Section,
    at: usize,
    element: Stateful<Div>,
    cx: &mut Context<Self>,
) -> Stateful<Div> {
    let gap = self.gap.clone();
    let shown = gap.get() == Some((section, at));
    element
        .relative()
        .on_drag_move(move |event: &DragMoveEvent<StoryDrag>, window, _| {
            if event.bounds.contains(&event.event.position) && gap.get() != Some((section, at))
            {
                gap.set(Some((section, at)));
                window.refresh();
            }
        })
        .on_drop(cx.listener(move |this, drag: &StoryDrag, _, cx| {
            this.gap.set(None);
            this.move_story(&drag.name, section, at, cx);
        }))
        .when(shown, |this| {
            this.child(crate::prompt_mode::drop_indicator(false, false, cx))
        })
}

